blocks.code:
.header {
 display: flex;
 align-items: center;
 justify-content: space-between;
}

.hero {
 min-height: 300px;
 display: flex;
 justify-content: center;
 align-items: center;
}

.app-header {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 20px;
 padding: 16px 24px;
}

.nav-links {
 display: flex;
 gap: 18px;
 flex-wrap: wrap;
}

.course-list {
 display: flex;
 flex-wrap: wrap;
 gap: 20px;
}

.course-card {
 flex: 1 1 240px;
 padding: 24px;
 border: 1px solid #26334d;
 border-radius: 16px;
}

.app-header {
 display: flex;
 flex-direction: column;
 align-items: stretch;
}

.nav-links {
 justify-content: center;
}

.layout {
 display: flex;
 flex-direction: row;
 flex-wrap: wrap;
 justify-content: space-between;
 align-items: center;
 gap: 16px;
}
